#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    /**
     * 方法一：一次遍歷（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int maxProfit(std::vector<int>& prices) {
        if (prices.empty()) {
            return 0;
        }

        int minPrice = INT_MAX;  // 歷史最低價格
        int maxProfit = 0;       // 最大利潤

        for (int price : prices) {
            if (price < minPrice) {
                // 更新最低價格
                minPrice = price;
            } else {
                // 計算今天賣出的利潤
                int profit = price - minPrice;
                maxProfit = std::max(maxProfit, profit);
            }
        }

        return maxProfit;
    }

    /**
     * 方法一：簡潔版本
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int maxProfit_clean(std::vector<int>& prices) {
        int minPrice = INT_MAX;
        int maxProfit = 0;

        for (int price : prices) {
            minPrice = std::min(minPrice, price);
            maxProfit = std::max(maxProfit, price - minPrice);
        }

        return maxProfit;
    }
};

